struct UnionFind {
    vector<ll> parent;

    UnionFind(ll n) {
        parent.resize(n);
        for (ll i = 0; i < n; ++i) parent[i] = i;
    }

    ll find(ll a) {
        if (parent[a] == a) return a;
        parent[a] = find(parent[a]);
        return parent[a];
    }

    void merge(ll a, ll b) {
        a = find(a);
        b = find(b);
        if (a != b) {
            if (rand() % 2) swap(a, b);
            parent[b] = a;
        }
    }
};

ll get_cycle_count(ll p, ll k) {
    UnionFind uf(p);
    for (ll i = 1; i < p; ++i) {
        ll target = (k * i) % p;
        uf.merge(i, target);
    }
    vector<bool> visited(p, false);
    ll count = 0;
    for (ll i = 1; i < p; ++i) {
        ll root = uf.find(i);
        if (!visited[root]) {
            visited[root] = true;
            ++count;
        }
