import java.util.*;

public class Main {
    static final long MOD = 1000000007;

    static class UnionFind {
        long[] parent;

        public UnionFind(int n) {
            parent = new long[n];
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        public long find(long a) {
            if (parent[(int)a] == a) {
                return a;
            }
            parent[(int)a] = find(parent[(int)a]);
            return parent[(int)a];
        }

        public void merge(long a, long b) {
            a = find(a);
            b = find(b);
            if (a != b) {
                Random rand = new Random();
                if (rand.nextInt(2) == 0) {
                    long temp = a;
                    a = b;
                    b = temp;
                }
                parent[(int)b] = a;
            }
        }
    }

    static long getCycleCount(int p, int k) {
        UnionFind uf = new UnionFind(p);
        for (int i = 1; i < p; i++) {
            int target = (k * i) % p;
            uf.merge(i, target);
        }
        boolean[] visited = new boolean[p];
        long count = 0;
        for (int i = 1; i < p; i++) {
            long root = uf.find(i);
            if (!visited[(int)root]) {
                visited[(int)root] = true;
                count++;
            }
        }
        return count;
    }

    static long computeSolutions(int p, int k) {
        long cycles;
        if (k == 0) {
            cycles = p - 1;
        } else if (k == 1) {
            cycles = p;
        } else {
            cycles = getCycleCount(p, k);
        }
        long res = 1;
        for (int i = 0; i < cycles; i++) {
            res = (res * p) % MOD;
        }
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();
        System.out.println(computeSolutions(p, k));
        int dummy = sc.nextInt(); // read dummy input
        sc.close();
    }
}
